package net.atlasauth.pca.mpc.net;

import java.math.BigInteger;
import java.util.List;
import java.util.function.IntFunction;
import net.atlasauth.pca.mpc.NetForensics.SlotDisclosure;
import net.atlasauth.pca.mpc.NetPa.AW;
import net.atlasauth.pca.mpc.NetPa.PA;

/** The offline material one party holds when the online phase starts, dealt by a trusted dealer or generated by the parties from OT. */
public final class Prep {
    /** The OT transcript of the triple products, kept to attribute a failed sacrifice (no-dealer mode only). */
    public record Forensics(BigInteger[] gadget, int rows, int slots, IntFunction<List<SlotDisclosure>> disclose) {}

    /** "trusted-dealer" or "no-dealer". A trusted dealer knows every share and key. */
    public final String mode;
    /** Whether the shares carry pairwise tags (identifiable abort); only the trusted-dealer mode provides them. */
    public final boolean tagged;
    public final BigInteger delta;
    public final PA[] alpha;
    /** triples[t] = a, b, c, then (a-hat, c-hat) per sacrifice partner. */
    public final AW[][] triples;
    /** Authenticated masks (dealer) or input bits (no-dealer), indexed owner * C + chain. */
    public final AW[] inputs;
    public final BigInteger[] myPlain;
    public final AW checkMask;
    public final Forensics forensics;

    public Prep(String mode, boolean tagged, BigInteger delta, PA[] alpha, AW[][] triples, AW[] inputs, BigInteger[] myPlain, AW checkMask, Forensics forensics) {
        this.mode = mode;
        this.tagged = tagged;
        this.delta = delta;
        this.alpha = alpha;
        this.triples = triples;
        this.inputs = inputs;
        this.myPlain = myPlain;
        this.checkMask = checkMask;
        this.forensics = forensics;
    }
}
